tool.command:
set -euo pipefail;


mkdir -p '00_input/01_re-annotation_genomes/01_bacterial_genomes/02_mapping' '00_input/01_re-annotation_genomes/02_plasmid_sequences' '00_input/02_reference_NCBI_genomes/01_bacterial_genomes/02_mapping' '00_input/02_reference_NCBI_genomes/02_plasmid_sequences' '00_input/03_extrnal_files_for_M4/01_bacterial/01_GenBank' '00_input/03_extrnal_files_for_M4/01_bacterial/02_cds' '00_input/03_extrnal_files_for_M4/01_bacterial/03_Protein_genes' '00_input/03_extrnal_files_for_M4/02_plasmids/01_GenBank' '00_input/03_extrnal_files_for_M4/02_plasmids/02_cds' '00_input/03_extrnal_files_for_M4/02_plasmids/03_Protein_genes';



#for $f in $reannotation.bacterial_fna
mkdir -p '00_input/01_re-annotation_genomes/01_bacterial_genomes/02_mapping'; cp -L '$f' '00_input/01_re-annotation_genomes/01_bacterial_genomes/02_mapping/${f.element_identifier}.fna';
#end for


#for $f in $reannotation.bacterial_gff
mkdir -p '00_input/01_re-annotation_genomes/01_bacterial_genomes/02_mapping'; cp -L '$f' '00_input/01_re-annotation_genomes/01_bacterial_genomes/02_mapping/${f.element_identifier}.gff';
#end for


#if $reannotation.plasmid_fna
#for $f in $reannotation.plasmid_fna
mkdir -p '00_input/01_re-annotation_genomes/02_plasmid_sequences'; cp -L '$f' '00_input/01_re-annotation_genomes/02_plasmid_sequences/${f.element_identifier}.fna';
#end for
#end if



#if $reannotation.plasmid_gff
#for $f in $reannotation.plasmid_gff
mkdir -p '00_input/01_re-annotation_genomes/02_plasmid_sequences'; cp -L '$f' '00_input/01_re-annotation_genomes/02_plasmid_sequences/${f.element_identifier}.gff';
#end for
#end if




#for $f in $reference.bacterial_fna
mkdir -p '00_input/02_reference_NCBI_genomes/01_bacterial_genomes/02_mapping'; cp -L '$f' '00_input/02_reference_NCBI_genomes/01_bacterial_genomes/02_mapping/${f.element_identifier}.fna';
#end for


#for $f in $reference.bacterial_gff
mkdir -p '00_input/02_reference_NCBI_genomes/01_bacterial_genomes/02_mapping'; cp -L '$f' '00_input/02_reference_NCBI_genomes/01_bacterial_genomes/02_mapping/${f.element_identifier}.gff';
#end for




#if $reference.plasmid_fna
#for $f in $reference.plasmid_fna
mkdir -p '00_input/02_reference_NCBI_genomes/02_plasmid_sequences'; cp -L '$f' '00_input/02_reference_NCBI_genomes/02_plasmid_sequences/${f.element_identifier}.fna';
#end for
#end if


#if $reference.plasmid_gff
