#for $f in $module4_inputs.bacterial_genbank
mkdir -p '00_input/03_extrnal_files_for_M4/01_bacterial/01_GenBank'; cp -L '$f' '00_input/03_extrnal_files_for_M4/01_bacterial/01_GenBank/${f.element_identifier}.gb';
