#for $f in $module4_inputs.bacterial_cds
mkdir -p '00_input/03_extrnal_files_for_M4/01_bacterial/02_cds'; cp -L '$f' '00_input/03_extrnal_files_for_M4/01_bacterial/02_cds/${f.element_identifier}.fna';
#end for


#for $f in $module4_inputs.bacterial_faa
mkdir -p '00_input/03_extrnal_files_for_M4/01_bacterial/03_Protein_genes'; cp -L '$f' '00_input/03_extrnal_files_for_M4/01_bacterial/03_Protein_genes/${f.element_identifier}.faa';
#end for


#if $module4_inputs.plasmid_genbank
