#end for
#end if



cp -r '$__tool_directory__/03_scripts' .;
cp '$__tool_directory__/Snakefile' .;
cp '$__tool_directory__/Snakefile.cds_interpretation' .;
cp '$__tool_directory__/Snakefile.export_M4' .;


snakemake --snakefile Snakefile --cores '$threads' --use-conda --printshellcmds --rerun-incomplete all;
snakemake --snakefile Snakefile.export_M4 --cores '$threads' --use-conda --printshellcmds --rerun-incomplete all;
test -s '04_results/01_final_tables/module3_bacterial_summary.tsv';
test -s '04_results/01_final_tables/module3_plasmid_summary.tsv';
test -s '04_results/01_final_tables/CDS_mapping_summary_NCBI_reference_vs_Prodigal_reannotation.tsv';
test -s '04_results/01_final_tables/module3_legend.txt';

test -s '04_results/02_figures/03_cds_mapping_interpretation/Figure_1A_bacterial_chromosomes_NCBI_vs_Prodigal_CDS_mapping.png';
test -s '04_results/02_figures/03_cds_mapping_interpretation/Figure_1B_plasmids_NCBI_vs_Prodigal_CDS_mapping.png';
test -s '04_results/02_figures/03_cds_mapping_interpretation/Figure_2A_bacterial_chromosomes_mean_CDS_length_change.png';
test -s '04_results/02_figures/03_cds_mapping_interpretation/Figure_2B_plasmids_mean_CDS_length_change.png';

test -s '00_input/04_module4_ready_inputs/module4_ready_manifest.tsv';
tar -czf 'module4_ready_inputs.tar.gz' -C '00_input' '04_module4_ready_inputs';
test -s 'module4_ready_inputs.tar.gz';
